<?php
defined( 'ABSPATH' ) || exit;
final class EduFlow_Phase3_Admin {
	public function register(){foreach(array('save_teacher','teacher_status','save_batch','batch_status','batch_student','generate_classes','class_action') as $action){add_action('admin_post_eduflow_'.$action,array($this,$action));}}
	private static function guard($cap){if(!current_user_can($cap)){wp_die(esc_html__('You do not have permission to perform this action.','eduflow-core'));}}
	private function redirect($page,$result,$success){$error=is_wp_error($result);wp_safe_redirect(add_query_arg(array('page'=>$page,'eduflow_notice'=>rawurlencode($error?$result->get_error_message():$success),'notice_type'=>$error?'error':'success'),admin_url('admin.php')));exit;}
	private static function notice(){if(!empty($_GET['eduflow_notice'])){$type='error'===($_GET['notice_type']??'')?'error':'success';echo '<div class="notice notice-'.esc_attr($type).' is-dismissible"><p>'.esc_html(sanitize_text_field(wp_unslash($_GET['eduflow_notice']))).'</p></div>';}}
	private static function pages($total,$page,$per=20){echo wp_kses_post(paginate_links(array('base'=>add_query_arg('paged','%#%'),'current'=>$page,'total'=>max(1,(int)ceil($total/$per)))));}
	public static function teachers(){self::guard('eduflow_manage_teachers');global $wpdb;$institute=EduFlow_Settings::institute_db_id();$table=EduFlow_DB::table('teachers');$search=sanitize_text_field(wp_unslash($_GET['s']??''));$status=sanitize_key($_GET['status']??'');$page=max(1,absint($_GET['paged']??1));$where=array('institute_id=%d');$params=array($institute);if($search){$like='%'.$wpdb->esc_like($search).'%';$where[]='(canonical_id LIKE %s OR name LIKE %s OR mobile LIKE %s OR email LIKE %s)';array_push($params,$like,$like,$like,$like);}if(in_array($status,EduFlow_Teacher_Service::STATUSES,true)){$where[]='teacher_status=%s';$params[]=$status;}$base=' FROM '.$table.' WHERE '.implode(' AND ',$where);$total=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*)'.$base,...$params));$params[]=20;$params[]=($page-1)*20;$rows=$wpdb->get_results($wpdb->prepare('SELECT *'.$base.' ORDER BY created_at DESC LIMIT %d OFFSET %d',...$params),ARRAY_A);self::notice();?><div class="wrap eduflow-wrap"><h1>Teachers</h1><form method="get"><input type="hidden" name="page" value="eduflow-teachers"><input type="search" name="s" value="<?php echo esc_attr($search);?>" placeholder="ID, name, mobile, email"><select name="status"><option value="">All statuses</option><option value="active" <?php selected($status,'active');?>>Active</option><option value="paused" <?php selected($status,'paused');?>>Paused</option></select><?php submit_button('Filter','secondary','',false);?></form><table class="widefat striped"><thead><tr><th>ID</th><th>Name</th><th>Contact</th><th>Availability</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?php echo esc_html($row['canonical_id']);?></td><td><?php echo esc_html($row['name']);?></td><td><?php echo esc_html($row['mobile']);?><br><?php echo esc_html($row['email']);?></td><td><?php echo esc_html($row['available_days'].' '.$row['available_start_time'].'–'.$row['available_end_time']);?></td><td><?php echo esc_html($row['teacher_status']);?></td><td><a href="<?php echo esc_url(add_query_arg(array('page'=>'eduflow-teachers','edit'=>$row['id']),admin_url('admin.php')));?>#teacher-form">Edit</a> <?php $next='active'===$row['teacher_status']?'paused':'active';?><a href="<?php echo esc_url(wp_nonce_url(admin_url('admin-post.php?action=eduflow_teacher_status&record='.$row['id'].'&status='.$next),'eduflow_teacher_status_'.$row['id']));?>"><?php echo esc_html('active'===$next?'Activate':'Pause');?></a></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6">No teachers found.</td></tr><?php endif;?></tbody></table><?php self::pages($total,$page);self::teacher_form();?></div><?php }
	private static function teacher_form(){$id=absint($_GET['edit']??0);$row=$id?EduFlow_Teacher_Service::get($id):array();$row=is_array($row)?$row:array();$days=explode(',',$row['available_days']??'');?><div class="eduflow-card" id="teacher-form"><h2><?php echo $id?'Edit Teacher':'Create Teacher';?></h2><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="eduflow_save_teacher"><input type="hidden" name="record" value="<?php echo esc_attr($id);?>"><?php wp_nonce_field('eduflow_save_teacher');?><div class="eduflow-form-grid"><?php foreach(array('name','mobile','email','joining_date','available_start_time','available_end_time','maximum_daily_classes') as $key):?><label><?php echo esc_html(ucwords(str_replace('_',' ',$key)));?><input name="<?php echo esc_attr($key);?>" value="<?php echo esc_attr($row[$key]??'');?>" <?php echo false!==strpos($key,'time')?'type="time"':'';?> <?php echo 'joining_date'===$key?'type="date"':'';?>></label><?php endforeach;?><fieldset><legend>Available Days</legend><?php foreach(array('mon','tue','wed','thu','fri','sat','sun') as $day):?><label><input type="checkbox" name="available_days[]" value="<?php echo esc_attr($day);?>" <?php checked(in_array($day,$days,true));?>><?php echo esc_html(ucfirst($day));?></label> <?php endforeach;?></fieldset><label class="wide">Notes<textarea name="notes"><?php echo esc_textarea($row['notes']??'');?></textarea></label></div><?php submit_button($id?'Update Teacher':'Create Teacher');?></form></div><?php }
	public function save_teacher(){self::guard('eduflow_manage_teachers');check_admin_referer('eduflow_save_teacher');$input=wp_unslash($_POST);$id=absint($input['record']??0);$result=$id?EduFlow_Teacher_Service::update($id,$input):EduFlow_Teacher_Service::create($input);$this->redirect('eduflow-teachers',$result,$id?'Teacher updated.':'Teacher created.');}
	public function teacher_status(){self::guard('eduflow_manage_teachers');$id=absint($_GET['record']??0);check_admin_referer('eduflow_teacher_status_'.$id);$this->redirect('eduflow-teachers',EduFlow_Teacher_Service::set_status($id,sanitize_key($_GET['status']??'')),'Teacher status updated.');}
	public static function batches(){self::guard('eduflow_manage_batches');global $wpdb;$institute=EduFlow_Settings::institute_db_id();$table=EduFlow_DB::table('batches');$search=sanitize_text_field(wp_unslash($_GET['s']??''));$status=sanitize_key($_GET['status']??'');$page=max(1,absint($_GET['paged']??1));$where=array('institute_id=%d');$params=array($institute);if($search){$like='%'.$wpdb->esc_like($search).'%';$where[]='(canonical_id LIKE %s OR batch_name LIKE %s OR course LIKE %s)';array_push($params,$like,$like,$like);}if(in_array($status,EduFlow_Batch_Service::STATUSES,true)){$where[]='batch_status=%s';$params[]=$status;}$base=' FROM '.$table.' WHERE '.implode(' AND ',$where);$total=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*)'.$base,...$params));$params[]=20;$params[]=($page-1)*20;$rows=$wpdb->get_results($wpdb->prepare('SELECT *'.$base.' ORDER BY created_at DESC LIMIT %d OFFSET %d',...$params),ARRAY_A);self::notice();?><div class="wrap eduflow-wrap"><h1>Batches</h1><form method="get"><input type="hidden" name="page" value="eduflow-batches"><input type="search" name="s" value="<?php echo esc_attr($search);?>" placeholder="ID, name, course"><select name="status"><option value="">All statuses</option><?php foreach(EduFlow_Batch_Service::STATUSES as $v):?><option value="<?php echo esc_attr($v);?>" <?php selected($status,$v);?>><?php echo esc_html(ucfirst($v));?></option><?php endforeach;?></select><?php submit_button('Filter','secondary','',false);?></form><table class="widefat striped"><thead><tr><th>ID</th><th>Batch</th><th>Course</th><th>Teacher</th><th>Schedule</th><th>Capacity</th><th>Status/Actions</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?php echo esc_html($row['canonical_id']);?></td><td><?php echo esc_html($row['batch_name']);?></td><td><?php echo esc_html($row['course'].' / '.$row['level'].' / '.$row['class_type']);?></td><td><?php echo esc_html($row['teacher_id']?:'Unassigned');?></td><td><?php echo esc_html($row['days_of_week'].' '.$row['start_time'].'–'.$row['end_time']);?></td><td><?php echo esc_html(EduFlow_Batch_Service::active_count($row['id'],$institute).' / '.$row['capacity']);?></td><td><a href="<?php echo esc_url(add_query_arg(array('page'=>'eduflow-batches','edit'=>$row['id']),admin_url('admin.php')));?>#batch-form">Edit</a> <?php foreach(array('active'=>'Resume','paused'=>'Pause','closed'=>'Close') as $v=>$label):?><a href="<?php echo esc_url(wp_nonce_url(admin_url('admin-post.php?action=eduflow_batch_status&record='.$row['id'].'&status='.$v),'eduflow_batch_status_'.$row['id']));?>"><?php echo esc_html($label);?></a> <?php endforeach;?></td></tr><?php endforeach;?></tbody></table><?php self::pages($total,$page);self::batch_form();self::assignment_form();?></div><?php }
	private static function batch_form(){$id=absint($_GET['edit']??0);$row=$id?EduFlow_Batch_Service::get($id):array();$row=is_array($row)?$row:array();$days=explode(',',$row['days_of_week']??'');?><div class="eduflow-card" id="batch-form"><h2><?php echo $id?'Edit Batch':'Create Batch';?></h2><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="eduflow_save_batch"><input type="hidden" name="record" value="<?php echo esc_attr($id);?>"><?php wp_nonce_field('eduflow_save_batch');?><div class="eduflow-form-grid"><?php foreach(array('batch_name','course','level','teacher_id','capacity','start_time','end_time','start_date','end_date','timezone') as $key):?><label><?php echo esc_html(ucwords(str_replace('_',' ',$key)));?><input name="<?php echo esc_attr($key);?>" value="<?php echo esc_attr($row[$key]??('timezone'===$key?(EduFlow_Settings::get_all()['timezone']??'Asia/Kolkata'):''));?>" <?php echo false!==strpos($key,'time')&&'timezone'!==$key?'type="time"':'';?> <?php echo false!==strpos($key,'date')?'type="date"':'';?>></label><?php endforeach;?><label>Class Type<select name="class_type"><?php foreach(EduFlow_Admission_Service::CLASS_TYPES as $type):?><option value="<?php echo esc_attr($type);?>" <?php selected($row['class_type']??'',$type);?>><?php echo esc_html(ucwords($type));?></option><?php endforeach;?></select></label><fieldset><legend>Days</legend><?php foreach(array('mon','tue','wed','thu','fri','sat','sun') as $day):?><label><input type="checkbox" name="days_of_week[]" value="<?php echo esc_attr($day);?>" <?php checked(in_array($day,$days,true));?>><?php echo esc_html(ucfirst($day));?></label> <?php endforeach;?></fieldset></div><?php submit_button($id?'Update Batch':'Create Batch');?></form></div><?php }
	private static function assignment_form(){?><div class="eduflow-card"><h2>Student Assignment</h2><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><?php wp_nonce_field('eduflow_batch_student');?><input type="hidden" name="action" value="eduflow_batch_student"><label>Operation <select name="operation"><option value="assign">Assign</option><option value="remove">Remove</option><option value="transfer">Transfer</option></select></label> <label>Student DB ID <input type="number" min="1" name="student_id" required></label> <label>Batch DB ID <input type="number" min="1" name="batch_id" required></label> <label>Target Batch DB ID <input type="number" min="1" name="target_batch_id"></label><?php submit_button('Apply','secondary','',false);?></form></div><?php }
	public function save_batch(){self::guard('eduflow_manage_batches');check_admin_referer('eduflow_save_batch');$input=wp_unslash($_POST);$id=absint($input['record']??0);$result=$id?EduFlow_Batch_Service::update($id,$input):EduFlow_Batch_Service::create($input);$this->redirect('eduflow-batches',$result,$id?'Batch updated.':'Batch created.');}
	public function batch_status(){self::guard('eduflow_manage_batches');$id=absint($_GET['record']??0);check_admin_referer('eduflow_batch_status_'.$id);$this->redirect('eduflow-batches',EduFlow_Batch_Service::set_status($id,sanitize_key($_GET['status']??'')),'Batch status updated.');}
	public function batch_student(){self::guard('eduflow_manage_batches');check_admin_referer('eduflow_batch_student');$operation=sanitize_key($_POST['operation']??'');$batch=absint($_POST['batch_id']??0);$student=absint($_POST['student_id']??0);if('assign'===$operation){$result=EduFlow_Batch_Service::assign_student($batch,$student);}elseif('remove'===$operation){$result=EduFlow_Batch_Service::remove_student($batch,$student);}elseif('transfer'===$operation){$result=EduFlow_Batch_Service::transfer_student($batch,absint($_POST['target_batch_id']??0),$student);}else{$result=new WP_Error('invalid_operation','Invalid assignment operation.');}$this->redirect('eduflow-batches',$result,'Student assignment updated.');}
	public static function classes(){self::guard('eduflow_manage_classes');global $wpdb;$institute=EduFlow_Settings::institute_db_id();$table=EduFlow_DB::table('classes');$google=EduFlow_DB::table('google_events');$search=sanitize_text_field(wp_unslash($_GET['s']??''));$status=sanitize_key($_GET['status']??'');$page=max(1,absint($_GET['paged']??1));$where=array('c.institute_id=%d');$params=array($institute);if($search){$like='%'.$wpdb->esc_like($search).'%';$where[]='(c.canonical_id LIKE %s OR c.schedule_key LIKE %s)';array_push($params,$like,$like);}if(in_array($status,EduFlow_Class_Service::STATUSES,true)){$where[]='c.class_status=%s';$params[]=$status;}$base=' FROM '.$table.' c LEFT JOIN '.$google.' g ON g.lecture_id=c.id AND g.institute_id=c.institute_id WHERE '.implode(' AND ',$where);$total=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*)'.$base,...$params));$params[]=20;$params[]=($page-1)*20;$rows=$wpdb->get_results($wpdb->prepare('SELECT c.*,g.sync_status AS google_sync_status,g.google_meet_url,g.google_event_url'.$base.' ORDER BY c.start_datetime ASC LIMIT %d OFFSET %d',...$params),ARRAY_A);self::notice();?><div class="wrap eduflow-wrap"><h1>Classes</h1><form method="get"><input type="hidden" name="page" value="eduflow-classes"><input type="search" name="s" value="<?php echo esc_attr($search);?>" placeholder="Lecture ID"><select name="status"><option value="">All statuses</option><?php foreach(EduFlow_Class_Service::STATUSES as $v):?><option value="<?php echo esc_attr($v);?>" <?php selected($status,$v);?>><?php echo esc_html(ucfirst($v));?></option><?php endforeach;?></select><?php submit_button('Filter','secondary','',false);?></form><table class="widefat striped"><thead><tr><th>ID</th><th>Batch</th><th>Teacher</th><th>Student</th><th>Date</th><th>UTC Time</th><th>Status</th><th>Google Sync</th><th>Meet</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?php echo esc_html($row['canonical_id']);?></td><td><?php echo esc_html($row['batch_id']);?></td><td><?php echo esc_html($row['teacher_id']);?></td><td><?php echo esc_html($row['student_id']);?></td><td><?php echo esc_html($row['class_date'].' '.$row['timezone']);?></td><td><?php echo esc_html($row['start_datetime'].'–'.$row['end_datetime']);?></td><td><?php echo esc_html($row['class_status']);?></td><td><?php echo esc_html($row['google_sync_status']?:'not_required');?></td><td><?php if($row['google_meet_url']):?><a href="<?php echo esc_url($row['google_meet_url']);?>" target="_blank" rel="noopener noreferrer">Open Meet</a><?php else:?>Unavailable<?php endif;?></td><td><a href="<?php echo esc_url(add_query_arg(array('page'=>'eduflow-classes','edit'=>$row['id']),admin_url('admin.php')));?>#class-form">Reschedule</a> <a href="<?php echo esc_url(wp_nonce_url(admin_url('admin-post.php?action=eduflow_class_action&record='.$row['id'].'&do=cancel'),'eduflow_class_action_'.$row['id']));?>">Cancel</a> <a href="<?php echo esc_url(wp_nonce_url(admin_url('admin-post.php?action=eduflow_google_sync&record='.$row['id']),'eduflow_google_sync_'.$row['id']));?>"><?php echo 'failed'===$row['google_sync_status']?'Retry Sync':'Sync Google';?></a> <?php if($row['google_event_url']):?><a href="<?php echo esc_url($row['google_event_url']);?>" target="_blank" rel="noopener noreferrer">Open Event</a><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php self::pages($total,$page);self::class_forms();?></div><?php }
	private static function class_forms(){$id=absint($_GET['edit']??0);$row=$id?EduFlow_Class_Service::get($id):array();?><div class="eduflow-card"><h2>Generate Rolling Schedule</h2><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="eduflow_generate_classes"><?php wp_nonce_field('eduflow_generate_classes');?><label>Batch DB ID <input type="number" min="1" name="batch_id" required></label><?php submit_button('Generate Next 14 Days','secondary','',false);?></form></div><?php if($row):?><div class="eduflow-card" id="class-form"><h2>Reschedule <?php echo esc_html($row['canonical_id']);?></h2><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="eduflow_class_action"><input type="hidden" name="do" value="reschedule"><input type="hidden" name="record" value="<?php echo esc_attr($id);?>"><?php wp_nonce_field('eduflow_class_action_'.$id);?><label>Date <input type="date" name="class_date" value="<?php echo esc_attr($row['class_date']);?>"></label> <label>Teacher DB ID <input type="number" name="teacher_id" value="<?php echo esc_attr($row['teacher_id']);?>"></label> <label>Start <input type="time" name="start_time" required></label> <label>End <input type="time" name="end_time" required></label><?php submit_button('Reschedule','secondary','',false);?></form></div><?php endif;}
	public function generate_classes(){self::guard('eduflow_manage_classes');check_admin_referer('eduflow_generate_classes');$result=EduFlow_Class_Service::generate_batch(absint($_POST['batch_id']??0));$message=is_wp_error($result)?'':sprintf('%d created, %d already present, %d conflicts.', $result['created'],$result['skipped'],count($result['conflicts']));$this->redirect('eduflow-classes',$result,$message);}
	public function class_action(){self::guard('eduflow_manage_classes');$id=absint($_REQUEST['record']??0);check_admin_referer('eduflow_class_action_'.$id);$do=sanitize_key($_REQUEST['do']??'');$result='cancel'===$do?EduFlow_Class_Service::cancel($id):('reschedule'===$do?EduFlow_Class_Service::reschedule($id,wp_unslash($_POST)):new WP_Error('invalid_action','Invalid class action.'));$this->redirect('eduflow-classes',$result,'Lecture updated.');}
}
